@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-500-normal.woff2') format('woff2'); font-weight: 500; font-style: normal; font-display: swap; }
@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-600-normal.woff2') format('woff2'); font-weight: 600; font-style: normal; font-display: swap; }
@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-700-normal.woff2') format('woff2'); font-weight: 700; font-style: normal; font-display: swap; }
@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-800-normal.woff2') format('woff2'); font-weight: 800; font-style: normal; font-display: swap; }
@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-900-normal.woff2') format('woff2'); font-weight: 900; font-style: normal; font-display: swap; }
@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-700-italic.woff2') format('woff2'); font-weight: 700; font-style: italic; font-display: swap; }
@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-800-italic.woff2') format('woff2'); font-weight: 800; font-style: italic; font-display: swap; }
@font-face { font-family: 'Barlow Condensed'; src: url('/fonts/barlow-900-italic.woff2') format('woff2'); font-weight: 900; font-style: italic; font-display: swap; }
@font-face { font-family: 'Inter'; src: url('/fonts/inter-400-normal.woff2') format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: 'Inter'; src: url('/fonts/inter-500-normal.woff2') format('woff2'); font-weight: 500; font-style: normal; font-display: swap; }
@font-face { font-family: 'Inter'; src: url('/fonts/inter-600-normal.woff2') format('woff2'); font-weight: 600; font-style: normal; font-display: swap; }

:root {
  --orange: #ff5b22;
  --orange-bright: #ff7a2f;
  --orange-soft: #ffb36b;
  --cyan: #48f2dc;
  --ink: #080b10;
  --ink-2: #111822;
  --paper: #fff7ec;
  --muted: rgba(255, 247, 236, 0.58);
  --glass: rgba(10, 15, 22, 0.54);
  --line: rgba(255, 255, 255, 0.16);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }
html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #080b10; }
body {
  font-family: 'Inter', system-ui, sans-serif;
  color: var(--paper);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  touch-action: none;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
kbd {
  font-family: 'Barlow Condensed', sans-serif;
  font-weight: 700;
  font-size: 0.74em;
  letter-spacing: 0.08em;
  border: 1px solid rgba(255,255,255,0.28);
  border-bottom-color: rgba(255,255,255,0.12);
  border-radius: 4px;
  padding: 0.25em 0.45em 0.2em;
  background: rgba(255,255,255,0.08);
  color: #fff;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.is-hidden { display: none !important; }

#app {
  position: fixed;
  inset: 0;
  isolation: isolate;
  background: #12202c;
}
#scene {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  display: block;
  outline: none;
}
#sky-grade {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    linear-gradient(180deg, rgba(7,12,23,0.15) 0%, transparent 24%, transparent 64%, rgba(6,8,12,0.4) 100%),
    radial-gradient(120% 90% at 50% 45%, transparent 54%, rgba(3,5,9,0.34) 100%);
  mix-blend-mode: multiply;
}
#grain {
  position: absolute; inset: -20%; pointer-events: none; z-index: 3; opacity: 0.08;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.85'/%3E%3C/svg%3E");
  animation: grain 0.8s steps(2) infinite;
}
@keyframes grain {
  0% { transform: translate(0,0); } 25% { transform: translate(-2%,1%); }
  50% { transform: translate(1%,-2%); } 75% { transform: translate(2%,2%); }
  100% { transform: translate(-1%,-1%); }
}
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 4;
  box-shadow: inset 0 0 18vw rgba(0,0,0,0.48);
}

/* ---------------- LOADING ---------------- */
.loading {
  position: absolute; inset: 0; z-index: 100;
  background:
    radial-gradient(80% 70% at 62% 48%, rgba(255,91,34,0.12), transparent 60%),
    #070a10;
  display: flex; align-items: center; justify-content: center; flex-direction: column;
  transition: opacity 0.8s ease, visibility 0.8s;
}
.loading.is-done { opacity: 0; visibility: hidden; }
.loading__mark {
  position: relative; width: 90px; height: 100px; margin-bottom: 34px;
  font-family: 'Barlow Condensed'; font-style: italic; font-weight: 900;
  display: flex; align-items: center;
}
.loading__mark span {
  font-size: 110px; line-height: .75; letter-spacing: -0.07em;
  background: linear-gradient(180deg, #fff 10%, #ffc59c 60%, #ff5b22 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.loading__mark i {
  position: absolute; right: -21px; top: -8px; font-size: 52px; font-style: italic;
  color: var(--orange); transform: skewX(-8deg);
}
.loading__text { display: flex; flex-direction: column; align-items: center; gap: 7px; }
.loading__text span { font: 600 12px/1 'Inter'; letter-spacing: .32em; color: #fff; }
.loading__text small { font: 500 9px/1 'Inter'; letter-spacing: .27em; color: rgba(255,255,255,.4); }
.loading__bar { width: min(280px, 58vw); height: 1px; background: rgba(255,255,255,.14); margin-top: 26px; overflow: hidden; }
.loading__bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #ff5b22, #ffd4ae); box-shadow: 0 0 12px #ff5b22; transition: width .2s ease; }
.loading__number { position: absolute; right: 5vw; bottom: 4vh; font: italic 900 72px/1 'Barlow Condensed'; color: rgba(255,255,255,.09); letter-spacing: -0.04em; }

/* ---------------- TITLE ---------------- */
.title-screen {
  position: absolute; inset: 0; z-index: 20;
  display: flex; flex-direction: column; justify-content: center;
  padding: clamp(26px, 4vw, 64px) clamp(26px, 5.3vw, 92px) calc(clamp(22px, 3.6vw, 52px) + var(--safe-bottom));
  transition: opacity .7s ease, visibility .7s;
}
.title-screen.is-hidden { display: flex !important; opacity: 0; visibility: hidden; pointer-events: none; }
.title-shade {
  position: absolute; inset: 0; z-index: -1;
  background:
    linear-gradient(90deg, rgba(4,7,12,.86) 0%, rgba(4,7,12,.58) 28%, rgba(4,7,12,.08) 60%, transparent 80%),
    linear-gradient(0deg, rgba(4,7,12,.72) 0%, transparent 23%, transparent 82%, rgba(4,7,12,.26) 100%);
}
.title-nav {
  position: absolute; top: clamp(19px, 2.8vw, 38px); left: clamp(26px, 5.3vw, 92px); right: clamp(26px, 5.3vw, 92px);
  display: flex; align-items: center; gap: 26px;
  font: 600 9px/1 'Inter'; letter-spacing: .24em;
}
.mini-mark { position: relative; display: flex; align-items: flex-start; height: 28px; padding-right: 20px; border-right: 1px solid var(--line); }
.mini-mark span { font: italic 900 27px/.9 'Barlow Condensed'; color: #fff; letter-spacing: -0.08em; }
.mini-mark i { font: italic 900 15px/.8 'Barlow Condensed'; color: var(--orange); margin-left: 2px; transform: translateY(2px); }
.live { display: flex; align-items: center; gap: 8px; color: rgba(255,255,255,.76); }
.live i { width: 5px; height: 5px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 9px var(--orange); animation: pulse 1.8s infinite; }
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: .35; } }
.locale { margin-left: auto; color: rgba(255,255,255,.52); }
.locale span { color: rgba(255,255,255,.31); margin-left: 9px; }
.title-content { position: relative; z-index: 2; width: min(680px, 62vw); }
.brand { display: flex; flex-direction: column; align-items: flex-start; }
.forza {
  font: 700 clamp(13px, 1.15vw, 19px)/1 'Inter';
  letter-spacing: .64em; color: rgba(255,255,255,.64); margin-left: 8px; margin-bottom: 10px;
  text-transform: uppercase;
}
.horizon-lockup { display: flex; align-items: flex-start; position: relative; }
.horizon-lockup h1 {
  margin: 0; font-family: 'Barlow Condensed'; font-style: italic; font-weight: 900;
  font-size: clamp(92px, 13.2vw, 212px); line-height: .72; letter-spacing: -.045em;
  text-transform: uppercase; color: #fff;
  text-shadow: 0 6px 40px rgba(0,0,0,.2);
  transform: skewX(-2deg);
  background: linear-gradient(180deg, #ffffff 18%, #fff3e3 62%, #ffb87e 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.six {
  margin-left: .06em; margin-top: -.08em;
  font: italic 900 clamp(76px, 10.4vw, 170px)/.8 'Barlow Condensed';
  color: var(--orange);
  text-shadow: 0 0 40px rgba(255,91,34,.4);
  transform: skewX(-5deg);
}
.sub-brand {
  display: flex; align-items: center; gap: 11px; margin-top: 20px;
  font: 600 clamp(11px, 1.25vw, 16px)/1 'Barlow Condensed'; letter-spacing: .42em; color: rgba(255,255,255,.85);
}
.sub-brand i { display: block; width: clamp(18px, 3vw, 44px); height: 1px; background: var(--orange); }
.tagline {
  margin: clamp(24px, 3.3vw, 42px) 0 0;
  font: italic 800 clamp(21px, 2.1vw, 31px)/1.03 'Barlow Condensed';
  letter-spacing: .01em; color: #fff;
}
.title-actions { display: flex; align-items: center; gap: 12px; margin-top: clamp(22px, 3vw, 38px); flex-wrap: wrap; }
.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: space-between; gap: 32px;
  height: 56px; padding: 0 18px 0 25px; min-width: 248px;
  font: 700 13px/1 'Inter'; letter-spacing: .16em; text-transform: uppercase;
  transition: transform .18s ease, background .18s ease, border-color .18s ease, color .18s ease;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
}
.btn span { transform: translateY(1px); }
.btn kbd { opacity: .55; border-color: rgba(255,255,255,.2); }
.btn--primary { background: var(--orange); color: #130b06; box-shadow: 0 10px 36px rgba(255,80,24,.25); }
.btn--primary:hover { background: #ff733f; transform: translateY(-2px); }
.btn--ghost { background: rgba(255,255,255,.055); border: 1px solid rgba(255,255,255,.22); color: #fff; min-width: 184px; backdrop-filter: blur(10px); }
.btn--ghost:hover { background: rgba(255,255,255,.11); border-color: rgba(255,255,255,.4); transform: translateY(-2px); }
.btn:active { transform: translateY(0); }
.title-meta {
  display: flex; gap: clamp(18px, 2.2vw, 36px); margin-top: clamp(30px, 4vw, 50px);
  font: 600 9px/1 'Inter'; letter-spacing: .18em; color: rgba(255,255,255,.42);
}
.title-meta span { display: flex; gap: 8px; align-items: center; }
.title-meta b { color: var(--orange); font-weight: 600; }
.title-side {
  position: absolute; right: clamp(26px, 5.3vw, 92px); bottom: clamp(110px, 14vh, 160px); z-index: 2;
  text-align: right;
}
.chapter { font: 600 9px/1 'Inter'; letter-spacing: .22em; color: rgba(255,255,255,.45); margin-bottom: 14px; }
.chapter span { color: var(--orange); margin: 0 6px; }
.car-name { font: 500 10px/1 'Inter'; letter-spacing: .22em; color: rgba(255,255,255,.62); }
.car-name strong { display: block; font: italic 900 clamp(32px, 3.2vw, 48px)/.9 'Barlow Condensed'; letter-spacing: .04em; color: #fff; margin-top: 3px; }
.car-name span { display: block; font: 600 9px/1 'Inter'; letter-spacing: .22em; color: var(--orange-soft); margin-top: 8px; }
.title-footer {
  position: absolute; left: clamp(26px, 5.3vw, 92px); right: clamp(26px, 5.3vw, 92px); bottom: calc(clamp(18px, 2.8vw, 35px) + var(--safe-bottom));
  display: flex; align-items: center; gap: 24px;
  font: 500 9px/1 'Inter'; letter-spacing: .13em; color: rgba(255,255,255,.45);
}
.key-guide { display: flex; gap: 22px; }
.key-guide span { display: flex; align-items: center; gap: 7px; }
.disclaimer { margin-left: auto; letter-spacing: .1em; color: rgba(255,255,255,.24); font-size: 8px; }
.build { padding-left: 22px; border-left: 1px solid var(--line); color: rgba(255,255,255,.3); }
.build span { color: var(--orange); }

/* ---------------- HUD ---------------- */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud-top {
  position: absolute; top: 24px; left: 26px; right: 26px;
  display: flex; align-items: flex-start; gap: 20px;
}
.event-chip {
  min-width: 182px; padding: 11px 14px 12px;
  background: linear-gradient(90deg, rgba(7,11,17,.78), rgba(7,11,17,.16));
  border-left: 2px solid var(--orange);
  backdrop-filter: blur(10px);
  display: flex; flex-direction: column; gap: 4px;
}
.event-chip__kicker { font: 600 8px/1 'Inter'; letter-spacing: .22em; color: var(--orange-soft); }
.event-chip strong { font: 700 13px/1.1 'Barlow Condensed'; letter-spacing: .12em; color: #fff; }
.event-chip__meta { font: 500 8px/1 'Inter'; letter-spacing: .12em; color: rgba(255,255,255,.46); margin-top: 2px; }
.race-strip {
  display: flex; align-items: center; gap: 18px;
  margin: 0 auto; padding: 10px 20px;
  background: rgba(7,11,17,.65); backdrop-filter: blur(12px);
  border: 1px solid rgba(255,255,255,.08);
  clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 12px, calc(100% - 12px) 100%, 12px 100%, 0 12px);
}
.race-stat { display: flex; flex-direction: column; gap: 3px; min-width: 45px; text-align: center; }
.race-stat span { font: 600 7px/1 'Inter'; letter-spacing: .2em; color: rgba(255,255,255,.42); }
.race-stat strong { font: 700 21px/.95 'Barlow Condensed'; letter-spacing: .04em; color: #fff; }
.race-stat strong span { font-size: 11px; color: rgba(255,255,255,.4); margin-left: 2px; letter-spacing: .05em; }
.race-stat--time { min-width: 108px; }
.race-stat--time strong { font-variant-numeric: tabular-nums; letter-spacing: .02em; }
.race-divider { width: 1px; height: 25px; background: rgba(255,255,255,.12); }
.hud-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; pointer-events: auto; }
.wallet {
  height: 36px; padding: 0 12px; display: flex; align-items: center; gap: 7px;
  font: 700 12px/1 'Barlow Condensed'; letter-spacing: .08em;
  background: rgba(7,11,17,.58); border: 1px solid rgba(255,255,255,.08); backdrop-filter: blur(10px);
}
.wallet__icon { color: var(--orange); font-size: 8px; }
.wallet small { font: 600 7px/1 'Inter'; color: rgba(255,255,255,.4); letter-spacing: .12em; margin-left: -2px; }
.icon-btn {
  width: 36px; height: 36px; display: grid; place-items: center;
  background: rgba(7,11,17,.58); border: 1px solid rgba(255,255,255,.08); backdrop-filter: blur(10px);
  transition: background .15s, color .15s;
}
.icon-btn svg { width: 15px; height: 15px; fill: rgba(255,255,255,.75); }
.icon-btn:hover { background: rgba(255,255,255,.12); }
.icon-btn.is-muted svg { fill: rgba(255,255,255,.28); }
.icon-btn.is-muted::after { content: ''; position: absolute; width: 18px; height: 1px; background: rgba(255,255,255,.45); transform: rotate(-45deg); }
.icon-btn { position: relative; }

.checkpoint-callout {
  position: absolute; top: 92px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px; padding: 8px 14px 8px 10px;
  background: rgba(8,13,20,.72); backdrop-filter: blur(10px);
  border: 1px solid rgba(72,242,220,.22);
  color: #fff;
}
.checkpoint-callout > span { color: var(--cyan); font-size: 14px; text-shadow: 0 0 10px var(--cyan); transition: transform .2s; }
.checkpoint-callout div { display: flex; flex-direction: column; gap: 2px; }
.checkpoint-callout small { font: 600 7px/1 'Inter'; letter-spacing: .18em; color: rgba(255,255,255,.42); }
.checkpoint-callout strong { font: 700 13px/1 'Barlow Condensed'; letter-spacing: .09em; }
.checkpoint-callout strong span { font-size: 10px; color: rgba(255,255,255,.45); }

.hud-bottom {
  position: absolute; left: 26px; right: 26px; bottom: calc(22px + var(--safe-bottom));
  display: flex; align-items: flex-end; justify-content: space-between; gap: 20px;
}
.map-wrap {
  width: 174px; padding: 8px 8px 6px; position: relative;
  background: linear-gradient(160deg, rgba(8,12,18,.72), rgba(8,12,18,.46));
  border: 1px solid rgba(255,255,255,.09); backdrop-filter: blur(10px);
}
.map-head { display: flex; justify-content: space-between; align-items: center; padding: 0 2px 6px; }
.map-head span { font: 600 7px/1 'Inter'; letter-spacing: .16em; color: rgba(255,255,255,.55); }
.map-head small { font: 700 8px/1 'Barlow Condensed'; color: var(--orange); }
#minimap { width: 158px; height: 158px; display: block; border-radius: 50%; background: radial-gradient(circle, rgba(16,27,34,.55), rgba(4,7,10,.25)); }
.map-scale { display: flex; align-items: center; gap: 5px; padding: 4px 3px 0; }
.map-scale i { display: block; width: 21px; height: 2px; background: rgba(255,255,255,.36); }
.map-scale span { font: 500 6px/1 'Inter'; letter-spacing: .15em; color: rgba(255,255,255,.34); }
.toast-zone { align-self: flex-end; display: flex; flex-direction: column; align-items: center; gap: 8px; margin-bottom: 10px; }
.toast {
  display: flex; align-items: center; gap: 9px; padding: 9px 16px;
  background: rgba(7,11,17,.8); border: 1px solid rgba(255,255,255,.12); backdrop-filter: blur(12px);
  animation: toast-in .35s cubic-bezier(.2,.8,.2,1);
}
.toast span { color: var(--orange); font-size: 11px; }
.toast p { margin: 0; font: 600 10px/1 'Inter'; letter-spacing: .12em; color: rgba(255,255,255,.9); }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px) scale(.98); } to { opacity: 1; transform: none; } }
.controls-hint { display: flex; gap: 13px; padding: 5px 10px; font: 500 7px/1 'Inter'; letter-spacing: .1em; color: rgba(255,255,255,.32); background: rgba(5,8,12,.3); }
.controls-hint span { display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.controls-hint kbd { font-size: 7px; padding: 2px 3px; border-color: rgba(255,255,255,.14); background: rgba(255,255,255,.04); color: rgba(255,255,255,.45); }
.drift-readout {
  position: absolute; right: 28px; bottom: 214px; display: flex; align-items: baseline; gap: 8px;
  padding: 7px 12px; border-right: 2px solid var(--orange); background: linear-gradient(270deg, rgba(9,13,19,.7), transparent);
  text-align: right; animation: drift-in .2s ease;
}
.drift-readout span { font: 600 8px/1 'Inter'; letter-spacing: .2em; color: var(--orange-soft); }
.drift-readout strong { font: italic 800 31px/1 'Barlow Condensed'; color: #fff; font-variant-numeric: tabular-nums; }
.drift-readout em { font: 700 11px/1 'Barlow Condensed'; font-style: normal; color: var(--orange); }
@keyframes drift-in { from { opacity: 0; transform: translateX(14px); } to { opacity: 1; transform: none; } }

.speed-cluster { position: relative; width: 278px; display: flex; align-items: flex-end; justify-content: flex-end; }
.gear { position: absolute; left: 6px; bottom: 12px; display: flex; flex-direction: column; align-items: center; gap: 2px; }
.gear span { font: 600 7px/1 'Inter'; letter-spacing: .16em; color: rgba(255,255,255,.38); }
.gear strong { font: italic 800 38px/.9 'Barlow Condensed'; color: rgba(255,255,255,.92); }
.speed-main { position: relative; width: 238px; height: 150px; }
.rpm-arc { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.rpm-arc__base { fill: none; stroke: rgba(255,255,255,.1); stroke-width: 3; stroke-linecap: round; }
.rpm-arc__fill { fill: none; stroke: url(#none); stroke: var(--orange); stroke-width: 3.5; stroke-linecap: round; stroke-dasharray: 100; stroke-dashoffset: 100; filter: drop-shadow(0 0 6px rgba(255,91,34,.55)); transition: stroke-dashoffset .08s linear; }
.speed-number { position: absolute; left: 0; right: 0; bottom: 30px; display: flex; align-items: baseline; justify-content: center; gap: 6px; }
.speed-number strong { font: italic 900 72px/.72 'Barlow Condensed'; letter-spacing: -.02em; color: #fff; text-shadow: 0 3px 26px rgba(0,0,0,.34); font-variant-numeric: tabular-nums; }
.speed-number span { font: 700 9px/1 'Barlow Condensed'; letter-spacing: .16em; color: rgba(255,255,255,.5); }
.speed-caption { position: absolute; bottom: 18px; left: 0; right: 0; display: flex; justify-content: center; gap: 20px; font: 600 7px/1 'Inter'; letter-spacing: .18em; color: rgba(255,255,255,.4); }
.speed-caption span:first-child { color: var(--orange-soft); }
.nitro { position: absolute; right: 183px; bottom: 1px; width: 5px; height: 100px; display: flex; flex-direction: column-reverse; align-items: center; gap: 8px; }
.nitro > span { writing-mode: vertical-rl; transform: rotate(180deg); font: 600 6px/1 'Inter'; letter-spacing: .16em; color: rgba(255,255,255,.35); }
.nitro__track { width: 4px; height: 80px; background: rgba(255,255,255,.12); display: flex; flex-direction: column-reverse; }
.nitro__track i { display: block; width: 100%; height: 100%; background: linear-gradient(0deg, #48f2dc, #d3fffa); box-shadow: 0 0 7px rgba(72,242,220,.7); transform-origin: bottom; transition: height .1s linear; }
.nitro.is-active .nitro__track i { background: linear-gradient(0deg, #ff5b22, #ffd0b5); box-shadow: 0 0 9px rgba(255,91,34,.8); }

/* ---------------- EVENT PROMPT / COUNTDOWN / ANNOUNCE ---------------- */
.event-prompt {
  position: absolute; z-index: 15; left: 50%; bottom: 25%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 13px; padding: 11px 18px 11px 12px;
  background: rgba(6,10,16,.78); border: 1px solid rgba(255,255,255,.13); backdrop-filter: blur(16px);
  box-shadow: 0 18px 50px rgba(0,0,0,.36);
  animation: prompt-in .4s cubic-bezier(.2,.8,.2,1);
}
@keyframes prompt-in { from { opacity: 0; transform: translate(-50%, 10px); } to { opacity: 1; transform: translate(-50%, 0); } }
.event-prompt__key {
  width: 38px; height: 38px; display: grid; place-items: center;
  border: 1px solid rgba(255,255,255,.36); border-radius: 3px; background: rgba(255,255,255,.07);
  font: 800 18px/1 'Barlow Condensed'; color: #fff;
}
.event-prompt > div:last-child { display: flex; flex-direction: column; gap: 3px; }
.event-prompt small { font: 600 7px/1 'Inter'; letter-spacing: .2em; color: var(--orange); }
.event-prompt strong { font: 700 17px/1 'Barlow Condensed'; letter-spacing: .1em; color: #fff; }
.event-prompt span { font: 500 7px/1 'Inter'; letter-spacing: .13em; color: rgba(255,255,255,.42); }
.countdown {
  position: absolute; inset: 0; z-index: 18; display: flex; flex-direction: column; align-items: center; justify-content: center;
  pointer-events: none; background: radial-gradient(circle, transparent 30%, rgba(4,6,10,.25) 100%);
}
.countdown span {
  font: italic 900 clamp(130px, 21vw, 310px)/.72 'Barlow Condensed'; color: #fff;
  text-shadow: 0 0 70px rgba(255,91,34,.5), 0 12px 50px rgba(0,0,0,.4);
  animation: count-pop .5s cubic-bezier(.16,1,.3,1);
}
.countdown small { margin-top: 20px; font: 700 10px/1 'Inter'; letter-spacing: .46em; color: rgba(255,255,255,.62); }
@keyframes count-pop { from { opacity: 0; transform: scale(1.5); filter: blur(8px); } to { opacity: 1; transform: scale(1); filter: blur(0); } }
.announcement {
  position: absolute; z-index: 19; left: 50%; top: 17%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 5px; text-align: center;
  padding: 14px 44px; background: linear-gradient(90deg, transparent, rgba(6,10,16,.86), transparent);
  animation: announce-in .5s cubic-bezier(.16,1,.3,1);
}
.announcement span { font: 600 8px/1 'Inter'; letter-spacing: .38em; color: var(--orange); }
.announcement strong { font: italic 900 clamp(30px, 4vw, 52px)/1 'Barlow Condensed'; letter-spacing: .04em; color: #fff; }
@keyframes announce-in { from { opacity: 0; transform: translate(-50%, -12px); } to { opacity: 1; transform: translate(-50%, 0); } }

/* ---------------- RESULTS ---------------- */
.results {
  position: absolute; inset: 0; z-index: 30; display: grid; place-items: center;
  background: radial-gradient(circle at 70% 45%, rgba(255,91,34,.12), transparent 40%), rgba(3,6,10,.68);
  backdrop-filter: blur(7px);
  animation: fade-in .5s ease;
}
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
.results__panel {
  width: min(600px, calc(100vw - 40px)); padding: 30px 34px 28px; position: relative;
  background: linear-gradient(155deg, rgba(18,26,36,.97), rgba(7,11,16,.98));
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: 0 40px 100px rgba(0,0,0,.5);
  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 0 100%);
  animation: panel-in .5s cubic-bezier(.16,1,.3,1);
}
@keyframes panel-in { from { opacity: 0; transform: translateY(24px) scale(.98); } to { opacity: 1; transform: none; } }
.results__panel::before { content: ''; position: absolute; left: 0; top: 0; width: 100%; height: 3px; background: linear-gradient(90deg, var(--orange), rgba(255,91,34,0)); }
.results__head { text-align: center; }
.results__head > span { font: 600 8px/1 'Inter'; letter-spacing: .35em; color: var(--orange); }
.position { margin-top: 8px; font: italic 900 92px/.82 'Barlow Condensed'; color: #fff; letter-spacing: -.02em; }
.position small { font-size: .38em; color: var(--orange); margin-left: 4px; letter-spacing: .04em; }
.results__head h2 { margin: 8px 0 0; font: italic 800 26px/1 'Barlow Condensed'; letter-spacing: .08em; color: #fff; }
.results__head p { margin: 6px 0 0; font: 500 8px/1 'Inter'; letter-spacing: .16em; color: rgba(255,255,255,.42); }
.results__stars { display: flex; justify-content: center; gap: 8px; margin: 13px 0 18px; }
.star { color: rgba(255,255,255,.13); font-size: 24px; text-shadow: none; }
.star.is-on { color: var(--orange); text-shadow: 0 0 16px rgba(255,91,34,.5); }
.results__stats { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid rgba(255,255,255,.09); border-bottom: 1px solid rgba(255,255,255,.09); padding: 16px 0; }
.results__stats div { text-align: center; border-right: 1px solid rgba(255,255,255,.08); display: flex; flex-direction: column; gap: 5px; }
.results__stats div:last-child { border: 0; }
.results__stats span { font: 600 7px/1 'Inter'; letter-spacing: .17em; color: rgba(255,255,255,.36); }
.results__stats strong { font: 700 21px/1 'Barlow Condensed'; letter-spacing: .04em; color: #fff; font-variant-numeric: tabular-nums; }
.results__stats strong span { font-size: 8px; letter-spacing: .08em; }
.results__reward { display: flex; align-items: baseline; gap: 10px; padding: 14px 4px 18px; }
.results__reward span { font: 600 7px/1 'Inter'; letter-spacing: .18em; color: rgba(255,255,255,.36); }
.results__reward strong { font: 700 18px/1 'Barlow Condensed'; letter-spacing: .06em; color: var(--orange-soft); }
.results__reward small { margin-left: auto; font: 600 8px/1 'Inter'; letter-spacing: .11em; color: rgba(255,255,255,.34); }
.results__actions { display: flex; gap: 10px; }
.results__actions .btn { height: 50px; flex: 1; min-width: 0; }
.results__actions .btn--primary { flex: 1.35; }

/* ---------------- PAUSE ---------------- */
.pause {
  position: absolute; inset: 0; z-index: 32; display: grid; place-items: center;
  background: rgba(3,6,10,.62); backdrop-filter: blur(10px); animation: fade-in .25s ease;
}
.pause__panel { width: min(480px, calc(100vw - 40px)); padding: 32px; background: rgba(10,15,22,.94); border: 1px solid rgba(255,255,255,.11); text-align: center; }
.eyebrow { font: 600 8px/1 'Inter'; letter-spacing: .34em; color: var(--orange); }
.pause h2 { margin: 9px 0 25px; font: italic 900 64px/.85 'Barlow Condensed'; letter-spacing: .03em; }
.pause__actions { display: flex; flex-direction: column; gap: 9px; }
.pause__actions .btn { width: 100%; min-width: 0; height: 50px; }
.pause__hint { margin-top: 22px; padding-top: 17px; border-top: 1px solid rgba(255,255,255,.09); font: 400 10px/1.5 'Inter'; color: rgba(255,255,255,.36); }

/* ---------------- TOUCH ---------------- */
.touch-controls { display: none; position: absolute; z-index: 14; left: 0; right: 0; bottom: calc(16px + var(--safe-bottom)); padding: 0 calc(16px + var(--safe-right)) 0 calc(16px + var(--safe-left)); pointer-events: none; }
.touch-steer, .touch-pedals { display: flex; align-items: flex-end; gap: 8px; pointer-events: auto; }
.touch-steer { position: absolute; left: 16px; bottom: 0; }
.touch-pedals { position: absolute; right: 16px; bottom: 0; }
.touch-controls button {
  width: 62px; height: 62px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.22); background: rgba(8,13,19,.54); backdrop-filter: blur(9px);
  font: 700 12px/1 'Barlow Condensed'; letter-spacing: .08em; color: rgba(255,255,255,.8);
  touch-action: none; transition: background .08s, transform .08s;
}
.touch-controls button.is-down { background: rgba(255,91,34,.7); border-color: rgba(255,150,100,.85); transform: scale(.94); }
.touch-steer button { width: 68px; height: 68px; font-size: 30px; }
.touch-pedals { gap: 9px; }
.touch-gas { width: 84px !important; height: 84px !important; background: rgba(255,91,34,.33) !important; border-color: rgba(255,130,75,.65) !important; }
.touch-small { width: 50px !important; height: 50px !important; font-size: 9px !important; }
.touch-small--nitro { color: var(--cyan); border-color: rgba(72,242,220,.35) !important; }
body.is-touch.playing .touch-controls { display: block; }
body.is-touch.playing.paused .touch-controls { display: none; }

#transition-flash { position: absolute; inset: 0; z-index: 50; background: #fff; opacity: 0; pointer-events: none; }
#transition-flash.flash { animation: flash .55s ease-out; }
@keyframes flash { 0% { opacity: .72; } 100% { opacity: 0; } }

/* ---------------- RESPONSIVE ---------------- */
@media (max-width: 980px) {
  .title-content { width: min(660px, 78vw); }
  .title-side { display: none; }
  .title-footer .key-guide { display: none; }
  .title-footer .disclaimer { margin-left: 0; }
  .title-footer { justify-content: space-between; }
  .controls-hint { display: none; }
  .hud-top { top: 16px; left: 16px; right: 16px; gap: 10px; }
  .hud-bottom { left: 16px; right: 16px; bottom: calc(16px + var(--safe-bottom)); }
  .speed-cluster { transform: scale(.9); transform-origin: bottom right; }
  .map-wrap { transform: scale(.9); transform-origin: bottom left; }
}
@media (max-width: 720px) {
  .title-screen { padding-left: 22px; padding-right: 22px; }
  .title-nav { left: 22px; right: 22px; top: 18px; }
  .locale { display: none; }
  .title-content { width: 100%; }
  .horizon-lockup h1 { font-size: clamp(84px, 19vw, 140px); }
  .six { font-size: clamp(64px, 15vw, 110px); }
  .forza { letter-spacing: .46em; font-size: 11px; }
  .sub-brand { font-size: 10px; margin-top: 12px; }
  .tagline { font-size: 19px; margin-top: 20px; }
  .title-actions { margin-top: 20px; }
  .title-meta { display: none; }
  .title-side { display: none; }
  .btn { height: 48px; min-width: 0; padding: 0 14px 0 18px; font-size: 11px; gap: 16px; }
  .title-actions .btn--primary { flex: 1.4; }
  .title-actions .btn--ghost { flex: 1; }
  .title-footer { font-size: 8px; }
  .disclaimer { display: none; }
  .title-footer { justify-content: flex-start; }
  .event-chip { min-width: 0; padding: 9px 10px; }
  .event-chip strong { font-size: 11px; }
  .event-chip__meta { display: none; }
  .race-strip { gap: 10px; padding: 8px 12px; }
  .race-stat { min-width: 34px; }
  .race-stat strong { font-size: 17px; }
